/** Material Symbols draw in a 960-unit box whose y runs from -960 to 0. */
private fun symbol(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f).apply {
        group(translationY = 960f) {
            paths.forEach { addPath(addPathNodes(it), fill = SolidColor(Color.Black)) }
        }
    }.build()
